def check_form(k):
    """Checks if k is of the form 2^a * 5^b."""
    if k == 0:
        return False
    while k > 1:
        if k % 2 == 0:
            k //= 2
        elif k % 5 == 0:
            k //= 5
        else:
            return False
    return True

def calculate_F(n):
    return n**2 + 2*n + 2

# Test for n from 0 to 50
n_values = range(51)
results = {}
for n in n_values:
    F_n = calculate_F(n)
    is_valid = check_form(F_n)
    results[n] = (F_n, is_valid)

print("n | F(n) | Valid (2^a 5^b)")
print("-" * 30)
for n, (Fn, valid) in results.items():
    print(f"{n:2} | {Fn:4} | {valid}")
